", "t": [["terminal", "{"command":"cd \"D:/Projects/local_ai/strata-lab/runs/work/hermes/jsondiff-1794053379\" && python - <<'EOF'\nfrom jsondiff import diff\ncases = [\n    ([1], [True]),                      # [~ $[0]: 1 -> true]\n    (None, False),                      # [~ $: null -> false]\n    (1, 1.0),                           # [~ $: 1 -> 1.0]\n    ({}, []),                           # [~ $: {} -> []]\n    ([], {}),                           # [~ $: [] -> {}]\n    ({\"a\": [1, 2]}, {\"a\": {\"b\": 1}}),   # [~ $.a: [1, 2] -> {\"b\": 1}]\n    ({\"a\": {\"x\": 1, \"y\": 2}}, {\"a\": {\"y\": 2}}),  # [- $.a.x: 1]\n    ([1, 2], [1, 2, 3]),                # [+ $[2]: 3]\n    (1, 1),                             # []\n    (True, True),                       # []\n    ({\"a\": None}, {\"a\": None}),         # []\n    ([{\"a\": 1}], [{\"a\": 1}]),           # []\n    ({\"n\": 1e3}, {\"n\": 1000.5}),        # [~ $.n: 1000.0 -> 1000.5]\n    ({\"b\": {\"z\": [1, [2, {\"k\": \"v\"}]]}, \"a\": 1},\n     {\"b\": {\"z\": [1, [2, {\"k\": \"w\"}]]}}),\n]\nfor a, b in cases:\n    print(repr(a), \"->\", repr(b), \"=>\", diff(a, b))\nEOF"}"]]}
